:host{container-type:inline-size}*,*::before,*::after{box-sizing:border-box}[role="meter"]{min-width:0}[role="meter"]>i,[role="meter"]>.mw-fill{width:0}@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important}}
.sf-card{--sf-cyan:#7dffd1;position:relative;isolation:isolate;width:100%;font-family:"Cascadia Code","Consolas","Courier New",monospace,"Malgun Gothic","맑은 고딕","Apple SD Gothic Neo",system-ui,sans-serif;font-size:12px;line-height:1.7;color:#b1ebd9;background:radial-gradient(ellipse at 0 0,#0e5c4933,transparent 60%),repeating-linear-gradient(0deg,#72ffd305 0 1px,transparent 1px 4px),#030e12;border:1px solid #2d8a70;border-radius:1px;overflow:hidden;overflow-wrap:anywhere;box-shadow:inset 0 0 26px #37ffbd0b;clip-path:polygon(0 0,calc(100% - 10px) 0,100% 10px,100% 100%,10px 100%,0 calc(100% - 10px))}
.sf-card::before{content:"";position:absolute;inset:0;pointer-events:none;z-index:2;background:linear-gradient(#8effdf,#8effdf) left top/26px 2px,linear-gradient(#8effdf,#8effdf) right bottom/26px 2px;background-repeat:no-repeat}.sf-card::after{content:"";position:absolute;inset:0;pointer-events:none;z-index:2;opacity:0;background:linear-gradient(0deg,transparent 46%,#7dffd30b 49%,#b9ffe35c 50%,transparent 50.3%)}
.sf-topline{display:flex;justify-content:space-between;gap:10px;padding:8px 13px;color:#76f8c6;border-bottom:1px solid #1a5a4c;background:#061e20;font-size:9px;line-height:1.5;letter-spacing:.08em;text-shadow:0 0 8px #66ffc550}.sf-topline>span:last-child{color:#3fba9b;font-size:8px;letter-spacing:2px;flex:none}.sf-ident{position:relative;display:flex;gap:13px;align-items:center;padding:19px 15px 18px;background:linear-gradient(90deg,#0c2a29a6,#031216),repeating-linear-gradient(90deg,transparent 0 17px,#2f705533 17px 18px);border-bottom:1px solid #23604f}.sf-emblem{position:relative;display:grid;place-items:center;width:49px;height:49px;flex:none;border:1px solid #4eeeb577;border-radius:50%;background:linear-gradient(90deg,transparent 49%,#7dffd340 50%,transparent 52%),linear-gradient(0deg,transparent 49%,#7dffd340 50%,transparent 52%);box-shadow:0 0 12px #34ffc225,inset 0 0 10px #1dba8622}.sf-emblem::before{content:"";position:absolute;inset:7px;border:1px solid #7dffd3;border-radius:50%;z-index:1}.sf-emblem::after{content:"";position:absolute;inset:4px;border-radius:50%;pointer-events:none;background:conic-gradient(transparent 0deg 230deg,#7dffd30f 270deg,#7dffd388 358deg,transparent 360deg)}.sf-emblem i{position:relative;z-index:1;display:block;width:7px;height:7px;transform:rotate(45deg);background:#caffea;box-shadow:0 0 9px #7dffd3}.sf-idinfo{flex:1;min-width:0}.sf-kicker{color:#64caa9;font-size:8px;letter-spacing:.12em}.sf-name{font-family:"Malgun Gothic","맑은 고딕","Apple SD Gothic Neo",system-ui,sans-serif;font-size:25px;line-height:1.4;letter-spacing:.03em;color:#d7fff0;text-shadow:0 0 13px #49ffc935;margin:6px 0 4px;font-weight:700}.sf-loc{font-size:9px;color:#8acbb9;margin:0;line-height:1.8}.sf-side{writing-mode:vertical-rl;font-size:8px;letter-spacing:.14em;color:#4bbd9b}
.sf-vital{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:14px;padding:18px 15px;border-bottom:1px solid #1a5145;background:linear-gradient(135deg,#103b302d,#031217)}.sf-label{display:block;font-size:10px;color:#79d9bc;letter-spacing:.04em}.sf-label small{font-family:"Malgun Gothic","맑은 고딕","Apple SD Gothic Neo",system-ui,sans-serif;font-size:9px;color:#729d92;margin-left:6px}.sf-hp{font-size:32px;line-height:1.2;letter-spacing:-.06em;font-weight:400;color:#a2ffd9;display:block;margin-top:9px;text-shadow:0 0 15px #54ffc94d}.sf-condition{min-width:0;padding:0}.sf-condition strong{display:inline-block;max-width:100%;font-size:11px;line-height:1.6;margin-top:8px;padding:1px 6px;color:#9bf9d1;border:1px solid #296852;background:#0d342a}.sf-condition p{font-family:"Malgun Gothic","맑은 고딕","Apple SD Gothic Neo",system-ui,sans-serif;font-size:10px;line-height:1.8;color:#9bd5c4;margin:7px 0 0}
.sf-section{padding:15px 15px 17px;border-bottom:1px solid #174c43}.sf-heading{display:flex;align-items:baseline;gap:7px;font-family:"Malgun Gothic","맑은 고딕","Apple SD Gothic Neo",system-ui,sans-serif;font-size:11px;font-weight:500;color:#c2f5e3;letter-spacing:.04em;margin:0 0 13px}.sf-heading>span{font-family:"Cascadia Code","Consolas","Courier New",monospace;font-size:10px;color:#7dffd1;text-shadow:0 0 7px #5fffc65e}.sf-heading small{font-family:"Cascadia Code","Consolas","Courier New",monospace;font-size:8px;letter-spacing:.09em;color:#5ab99c;margin-left:auto}
.sf-mission{display:flex;align-items:baseline;gap:10px;margin-top:10px}.sf-mission>span{font-size:9px;color:#65cdae;flex:none;min-width:38px}.sf-mission p{font-family:"Malgun Gothic","맑은 고딕","Apple SD Gothic Neo",system-ui,sans-serif;font-size:11px;line-height:1.85;color:#b3decf;margin:0;min-width:0}.sf-main{padding:10px 9px;border:1px solid #28654e;background:#0c302566;margin:0 0 12px;box-shadow:inset 0 0 14px #5bffa707}.sf-main>span{color:#9effcb;min-width:38px}.sf-main p{color:#dbffec;font-weight:500}
.sf-risk{display:flex;justify-content:space-between;gap:12px;align-items:baseline;padding-bottom:10px;margin-bottom:5px;border-bottom:1px dashed #22594c;font-family:"Malgun Gothic","맑은 고딕","Apple SD Gothic Neo",system-ui,sans-serif;font-size:10px;color:#81bea7}.sf-risk strong{font-family:"Cascadia Code","Consolas","Courier New",monospace;font-size:20px;font-weight:400;letter-spacing:.1em;color:#8dffd0;text-shadow:0 0 10px currentColor}.sf-risk[data-level="HIGH"] strong{color:#ffb385;text-shadow:0 0 12px #ff9b6844}.sf-risk[data-level="CRITICAL"] strong{color:#ff827b;text-shadow:0 0 12px #ff827b44}.sf-risk[data-level="MODERATE"] strong{color:#f0d795;text-shadow:0 0 12px #f0d79533}
.sf-metric{--tone:#7dffd1;margin-top:11px}.sf-danger{--tone:#ff9c83}.sf-warn{--tone:#edce82}.sf-safe{--tone:#75e8ed}.sf-metric>div:first-child{display:flex;justify-content:space-between;align-items:baseline;gap:12px;font-family:"Malgun Gothic","맑은 고딕","Apple SD Gothic Neo",system-ui,sans-serif;font-size:10px;color:#96d5bd;margin-bottom:6px}.sf-metric b{font-family:"Cascadia Code","Consolas","Courier New",monospace;font-size:14px;font-weight:400;color:var(--tone)}.sf-metric small{font-size:9px;color:#73a895}.sf-track{height:6px;background:repeating-linear-gradient(90deg,#163a30 0 8px,#041010 8px 10px);overflow:hidden;box-shadow:0 0 0 1px #153c31}.sf-track i{display:block;height:100%;transform-origin:left;background:repeating-linear-gradient(90deg,var(--tone) 0 8px,transparent 8px 10px);filter:drop-shadow(0 0 3px var(--tone))}
.sf-intel{padding:15px 15px 18px;background:#06201d44}.sf-intel p{font-family:"Malgun Gothic","맑은 고딕","Apple SD Gothic Neo",system-ui,sans-serif;font-size:11px;line-height:1.95;color:#9cd6c1;margin:10px 0 0;padding:0}.sf-foot{display:flex;gap:8px;align-items:center;padding:12px 15px 20px;border-top:1px solid #225c4d;background:#031013;font-size:8px;letter-spacing:.09em;color:#57b899}.sf-foot>span:first-child{color:#87ffd1;flex:none}.sf-foot>span:first-child::after{content:"";display:inline-block;width:5px;height:8px;background:#7dffd1;margin-left:5px;vertical-align:baseline;opacity:.6}.sf-footline{height:8px;max-width:37px;flex:1;margin-left:auto;background:repeating-linear-gradient(90deg,#67bd9944 0 1px,transparent 1px 4px)}
@keyframes sf-scan{0%{transform:translateY(-100%);opacity:0}8%,90%{opacity:.55}100%{transform:translateY(100%);opacity:0}}@keyframes sf-radar{to{transform:rotate(360deg)}}@keyframes sf-power-on{from{opacity:.15}to{opacity:1}}@keyframes sf-meter-on{from{transform:scaleX(0)}to{transform:scaleX(1)}}@keyframes sf-diode{0%,100%{opacity:.65}50%{opacity:1}}@keyframes sf-cursor{0%,55%{opacity:.85}56%,100%{opacity:0}}
@media(prefers-reduced-motion:no-preference){.sf-card::after{animation:sf-scan 7s .5s linear infinite}.sf-emblem::after{animation:sf-radar 5.5s linear infinite}.sf-emblem i{animation:sf-diode 3.8s ease-in-out infinite}.sf-ident,.sf-vital{animation:sf-power-on .5s ease-out both}.sf-section{animation:sf-power-on .6s .1s ease-out both}.sf-track i{animation:sf-meter-on 1.1s .2s ease-out both}.sf-warn .sf-track i{animation-delay:.3s}.sf-safe .sf-track i{animation-delay:.4s}.sf-foot>span:first-child::after{animation:sf-cursor 1.8s steps(1,end) infinite}.sf-card:hover::after{animation-play-state:paused}}
@container(max-width:280px){.sf-topline{padding-left:12px;padding-right:12px;font-size:8px;letter-spacing:.03em}.sf-ident{padding-left:12px;padding-right:12px;gap:10px}.sf-emblem{width:38px;height:38px}.sf-name{font-size:22px}.sf-kicker{font-size:7px;letter-spacing:.06em}.sf-side{display:none}.sf-vital{padding-left:12px;padding-right:12px;gap:10px}.sf-hp{font-size:27px}.sf-section{padding-left:12px;padding-right:12px}.sf-heading small{font-size:7px}.sf-loc{font-size:8px}}

