@keyframes sf-log-sweep{0%,40%{transform:translateX(-110%);opacity:0}44%{opacity:1}65%{transform:translateX(110%);opacity:1}66%,100%{transform:translateX(110%);opacity:0}}@keyframes sf-log-in{from{opacity:.2}to{opacity:1}}@media(prefers-reduced-motion:no-preference){.sf-shead::after{animation:sf-log-sweep 7s linear infinite}.sf-zone,.sf-feed{animation:sf-log-in .6s .1s ease-out both}}

